fields.InputDefinition:
{
  "goal": "You are logged in at http://localhost:4200. Navigate the browser's address bar directly to the deep-link URL http://localhost:4200/app/Admin and press Enter. Verify the Explorer resolves this route and loads the Admin application (its landing screen or a section list), rather than showing a 404, a blank page, or bouncing to Home. Seeing the Admin app render from the typed URL is success. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Navigating the address bar to /app/Admin loads the Admin application (its nav sections or landing render)",
    "The route resolves to the correct app rather than a not-found/blank page or an unexpected redirect to Home",
    "No error messages, blank screens, or crash pages"
  ]
}
